/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=note, operation=get
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Get an activity */
export type PipedriveV2NoteGetParams = {
  resource: 'note';
  operation: 'get';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the note to get
 * @default 0
 */
    noteId?: number | Expression<number>;
};

export type PipedriveV2NoteGetNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  credentials?: Credentials;
  config: NodeConfig<PipedriveV2NoteGetParams>;
};